                 //
                 // swap
                 //
                 //      {
                 //          "code": "0",
                 //          "msg": "Success",
                 //          "data": [{
                 //                  "orderId": 1917641,
                 //                  "clientOrderId": "2488514315",
                 //                  "price": 100,
                 //                  "origQty": 10,
